// Read-only publication views. Scenario choices never mutate the underlying data.
const MEASUREMENT = createMeasurementModel(DATA.measurement,RISKS.map(r=>r.risk_id),EX_DATA.controls.map(c=>c.id));
const RISK_STATISTIC = validatePresentation(DATA.presentation).riskStatistic;
const RISK_STATISTIC_LABEL = RISK_STATISTIC==='median'?'Median (P50)':'Medelvärde';
const REVIEWED_COST = DATA.measurement.priorityMetric==='reviewed_cost_indicator';
const CENTRAL_COST = REVIEWED_COST||DATA.measurement.priorityMetric==='median_product_annual_cost';
const primaryCost = row => priorityCost(row,DATA.measurement.priorityMetric);
const LOSS_STATISTIC = DATA.presentation.costPriority?'mean':RISK_STATISTIC;
const RISK_LOSS_LABEL = REVIEWED_COST?'Granskad kostnadsindikator / år':CENTRAL_COST?'Medianbaserad kostnadsindikator / år':LOSS_STATISTIC==='median'?'Medianförlust':'Förväntad kostnad / år';
const descriptionRange = (id,dimension) => {const row=MEASUREMENT.byRisk.get(id);return !row?.centralCost&&row?.review?.some(f=>f.dimension===dimension)?row.descriptionReview?.estimates.find(e=>e.dimension===dimension):null;};
const riskMetric = (id,dimension) => REVIEWED_COST?(dimension==='expectedLoss'?primaryCost(MEASUREMENT.byRisk.get(id)):MEASUREMENT.byRisk.get(id)?.reviewedInputs?.[dimension]||null):dimension==='expectedLoss'&&CENTRAL_COST?primaryCost(MEASUREMENT.byRisk.get(id)):descriptionRange(id,dimension)?null:MEASUREMENT.metric(id,dimension,dimension==='expectedLoss'?LOSS_STATISTIC:RISK_STATISTIC);
function measurementModeNote() {return `<div class="ms-statistic-note"><strong>${REVIEWED_COST?'Prioritering med angiven beräkningsgrund':CENTRAL_COST?'Medianbaserad prioritering':RISK_STATISTIC==='median'?'Median för frekvens och kostnad per händelse':'Medelvärde för frekvens och kostnad per händelse'}</strong><span>${REVIEWED_COST?'Jämförbara källuppgifter ersätter modellvärden som granskningen underkänner. Källintervall representeras av sin aritmetiska mittpunkt och redovisas i sin helhet. Övriga värden är modellmedianer. Produkten används för prioritering och är ingen uppmätt årskostnad.':CENTRAL_COST?'Kostnadsindikatorn är medianfrekvens × mediankostnad. Den beskriver ett centralt beräkningsläge och är varken förväntad årskostnad eller medianen för faktisk årsförlust. Medelvärden finns i riskens fördjupning.':'Förväntad årskostnad beräknas från medelvärden.'} Utgångsläget är utan införda motåtgärder.</span></div>`;}
const REPORT = DATA.report;
const INTERVIEWS = DATA.reportInterviews;
const publicationState = {controlTab:'register',selected:new Set(),controlDriver:'authority',controlSearch:'',analysisChart:'',analysisTop:false,chapter:null,expandedRisk:null};
function measurementControlStatus(c) {if(DATA.measurement.controlInvestment)return MEASUREMENT.byControl.has(c.id)?'Föreslagen · effektunderlag finns':'Föreslagen · effektunderlag saknas';return DATA.measurement.scenarios?.some(s=>s.controlIds.includes(c.id))?'Scenariounderlag finns':MEASUREMENT.byControl.has(c.id)?'Resultat på modellskala finns':'Effekt ej införd';}
const measurementNumber = value => typeof value==='number'&&Number.isFinite(value)?new Intl.NumberFormat('sv-SE',value!==0&&Math.abs(value)<.01?{maximumSignificantDigits:2}:{maximumFractionDigits:2}).format(value):'—';
const measurementCurrencyUnit = () => !DATA.measurement.provenance?.currency||DATA.measurement.provenance.currency==='SEK'?'mnkr':`mn ${DATA.measurement.provenance.currency}`;
const measurementMoney = value => value==null?'—':DATA.measurement.provenance?.currency==='SEK'&&Math.abs(value)>=1e9?`${measurementNumber(value/1e9)} mdkr`:`${measurementNumber(value/1e6)} ${measurementCurrencyUnit()}`;
function measurementPeriod(years=DATA.measurement.provenance?.horizonYears) {return years?`${measurementNumber(years*12)} månader`:'Period inväntas';}
function measurementLabel() {const p=DATA.measurement.provenance;return p?`${esc(p.displayLabel||p.label)} · ${measurementPeriod()} · ${esc(p.currency)}`:'Ny mätning inväntas';}
function measurementScope(statistic=LOSS_STATISTIC) {const count=CENTRAL_COST?RISKS.filter(r=>primaryCost(MEASUREMENT.byRisk.get(r.risk_id))).length:MEASUREMENT.aggregate(RISKS.map(r=>r.risk_id),statistic).quantified;return `<div class="ms-scope"><span>${measurementLabel()} · ${esc(DATA.measurement.provenance?.baselineLabel||'')}</span><span>${count} av ${RISKS.length} risker har ${REVIEWED_COST?'granskad kostnadsindikator':CENTRAL_COST?'medianbaserad kostnadsindikator':statistic==='median'?'förlustmedian':'förlustmedelvärde'}</span></div>`;}
function measurementAudit(id) { return DATA.numericAudit?.risks?.find(r=>r.riskId===id)||null; }
function measurementReviewLevel(id) {
 const level=measurementAudit(id)?.reviewLevel;
 return ({source_review:'Fördjupad källjämförelse',description_screen:'Beskrivningens numeriska innehåll samt aritmetik',arithmetic_only:'Aritmetik och datans ursprung',outside_execution:'Utanför mätningens urval'})[level]||(MEASUREMENT.byRisk.get(id)?.sourceReview?'Fördjupad källjämförelse':'Aritmetik och datans ursprung');
}
function measurementProvenanceMeta(id,dimension) {
  const row=MEASUREMENT.byRisk.get(id);
  return dimension==='expectedLoss'?costProvenance(row,DATA.measurement.priorityMetric||(LOSS_STATISTIC==='median'?'loss_median':'expected_annual_cost')):inputProvenance(row,dimension,{statistic:RISK_STATISTIC,effective:REVIEWED_COST});
}
function measurementProvenanceLabel(id,dimension) {
  const p=measurementProvenanceMeta(id,dimension);
  return `<small class="ms-value-provenance" data-value-origin="${esc(p.origin)}"><span>Ursprung: ${esc(p.sourceLabel)}</span><span>Mått: ${esc(p.statisticLabel)}</span></small>`;
}
function measurementMissingReason(id,dimension='expectedLoss') {
  const row=MEASUREMENT.byRisk.get(id),audit=measurementAudit(id),review=row?.sourceReview;
  if(!row)return 'Risken ingick inte i mätningen. Frekvens och kostnad saknar mätunderlag.';
  const missing=(audit?.missing||review?.missing||(audit?.missingReason?[audit.missingReason]:[])).map(x=>typeof x==='string'?x:x.reason||'').filter(Boolean);
  const flags=(row.review||[]).filter(x=>dimension==='expectedLoss'||x.dimension===dimension).map(x=>x.reason).filter(Boolean);
  return [...new Set([...missing,...flags])].join(' ')||review?.reason||'Jämförbart frekvens- eller kostnadsunderlag saknas. Värdet kan inte beräknas och räknas inte som noll.';
}
function measurementAggregateNote(ids) {
  const p=aggregateProvenance(DATA.measurement,ids);
  return `<p class="ms-aggregate-provenance"><strong>Ursprung och mått:</strong> ${esc(p.label)} Måttet är summan av separata beräknade produkter; modellmedianer och eventuella källintervalls mittpunkter framgår för varje risk. ${esc(p.detail)}</p>`;
}
function measurementControlProvenance() {
  const p=controlEffectProvenance();
  return `<aside class="ms-provenance-note"><strong>Ursprung: ${esc(p.sourceLabel)}</strong><span>Mått: ${esc(p.statisticLabel)}.</span><p>${esc(p.detail)}</p></aside>`;
}
function measurementValue(riskId,dimension) {
  const m=riskMetric(riskId,dimension),p=measurementProvenanceMeta(riskId,dimension);
  const recovered=!REVIEWED_COST&&descriptionRange(riskId,dimension);
  if(recovered)return `<strong>${measurementRange(recovered)}</strong><small class="ms-value-provenance"><span>Ursprung: riskbeskrivningens bedömning</span><span>Mått: intervall</span></small>`;
  if(!m)return `<span class="ms-unmeasured">Ej definierat</span>${measurementProvenanceLabel(riskId,dimension)}<small class="ms-missing-reason">${esc(measurementMissingReason(riskId,dimension))}</small>`;
  const value=dimension==='likelihood'?(m.unit==='probability'?measurementNumber(m.value*100)+' %':measurementNumber(m.value)+' / år'):measurementMoney(m.value);
  const range=p.lower!=null&&p.upper!=null&&p.lower!==p.upper?`<small class="ms-source-interval">Källintervall: ${dimension==='likelihood'?measurementNumber(p.lower)+'–'+measurementNumber(p.upper)+' / år':measurementMoney(p.lower)+'–'+measurementMoney(p.upper)}</small>`:'';
  return `<strong>${value}</strong>${measurementProvenanceLabel(riskId,dimension)}${range}`;
}
function measurementStrip(id) {
  const r={likelihood:riskMetric(id,'likelihood')};
  return `${measurementModeNote()}<div class="ms-metrics"><div><span>${r?.likelihood?.unit==='events_per_year'||descriptionRange(id,'likelihood')?'Händelser i Sverige':'Sannolikhet'}</span>${measurementValue(id,'likelihood')}</div><div><span>Kostnad vid händelse</span>${measurementValue(id,'impact')}</div><div><span>${RISK_LOSS_LABEL}</span>${measurementValue(id,'expectedLoss')}</div></div>`;
}
function measurementFormula(id) {
  const r=MEASUREMENT.byRisk.get(id),value=riskMetric(id,'expectedLoss');
  if(REVIEWED_COST){const c=r?.reviewedCost,l=r?.reviewedInputs?.likelihood,i=r?.reviewedInputs?.impact;return c?`${measurementProvenanceLabel(id,'expectedLoss')}<p>Granskad kostnadsindikator: <strong>${measurementNumber(l.value)} händelser/år × ${measurementMoney(i.value)} ≈ ${measurementMoney(c.value)} per år</strong>.</p>${c.lower!==c.upper?`<p>Källbaserat beräkningsintervall: <strong>${measurementMoney(c.lower)}–${measurementMoney(c.upper)} per år</strong>. Intervallet varierar de ersatta källuppgifterna och håller kvarvarande modellmedianer fasta. Det är inget statistiskt osäkerhetsintervall.</p>`:''}<p class="ex-note">Beräkningen använder oavrundade indata; de visade talen är avrundade. Källintervall använder sin aritmetiska mittpunkt. Ursprungliga modellvärden finns i fördjupningen.</p>${measurementMeanComparison(id)}`:'<p>Kostnadsindikatorn är odefinierad efter källgranskningen. Risken finns kvar; se förklaringen och källuppgifterna ovan.</p>'; }
  if(CENTRAL_COST)return r?.centralCost?`<p>Medianbaserad kostnadsindikator: <strong>${measurementNumber(r.summaries.likelihood.median)} händelser/år × ${measurementMoney(r.summaries.impact.median)} ≈ ${measurementMoney(r.centralCost.value)} per år</strong>.</p><p class="ex-note">Detta är produkten av två kalibrerade medianer, inte medianen för faktiskt utfall under ett år. Risker med breda osäkerhetsfördelningar behålls, men de höga medelvärdena styr inte huvudrangordningen.</p>${measurementMeanComparison(id)}`:`<p>Medianbaserad kostnadsindikator saknas. Jämförbar medianfrekvens eller mediankostnad behöver klargöras.</p>${measurementReview(id)}`;
  if(LOSS_STATISTIC==='median')return `<p>Medianförlust: <strong>${measurementMoney(value?.value)}</strong>.</p><p class="ex-note">${value?'P50 från riskens monetära förlustfördelning under den angivna perioden.':'Median för riskens monetära förlust har ännu inte införts.'} Medianerna för sannolikhet och konsekvens multipliceras inte till en förlustmedian.</p>`;
  if(!r?.expectedLoss)return `<p>Förväntad kostnad är odefinierad i denna utgåva.</p>${measurementReview(id)}`;
  if(r.expectedLoss.method==='product_of_means') {
    const likelihood=MEASUREMENT.metric(id,'likelihood','mean'),impact=MEASUREMENT.metric(id,'impact','mean');
    return `<p>Förväntad årskostnad: <strong>${likelihood.unit==='probability'?measurementNumber(likelihood.value*100)+' %':measurementNumber(likelihood.value)+' händelser/år'} × ${measurementMoney(impact.value)}${likelihood.unit==='events_per_year'?` × ${measurementNumber(DATA.measurement.provenance.horizonYears)} år`:''} ≈ ${measurementMoney(value.value)}</strong></p><p class="ex-note">Produkten använder medelvärden och angivet antagande om oberoende mellan händelsemått och konsekvenskostnad.</p>`;
  }
  return `<p>Förväntad årskostnad: <strong>${measurementMoney(value?.value)}</strong>. Exporterat medelvärde från den gemensamma förlustberäkningen.</p>`;
}
function measurementMeanComparison(id) {
 const r=MEASUREMENT.byRisk.get(id);if(!r?.centralCost)return '';
 const l=r.summaries.likelihood,i=r.summaries.impact,m=r.expectedLoss;
 return `<details class="ex-method ms-mean-comparison"><summary>Ursprunglig modell · årsmedelvärde${m?' · '+measurementMoney(m.value):' · ej definierat'}</summary><p class="ex-note">Ursprung: mätresultat från den ursprungliga modellen. Mått: beräknad produkt av modellmedelvärden.</p><p>${m?`Medelfrekvens ${measurementNumber(l.mean)} händelser/år × medelkostnad ${measurementMoney(i.mean)} ≈ ${measurementMoney(m.value)} per år. Det är ${measurementNumber(m.value/r.centralCost.value)} gånger den ursprungliga medianprodukten.`:'Årsmedelvärdet är odefinierat efter granskning. De användbara medianerna bevaras separat.'}</p><p>Medelvärdena påverkas av höga värden långt ut i modellens osäkerhetsfördelningar. Skillnaden beskriver modellens antaganden och osäkerhet; den är inte belägg för observerade kostnader. Årsmedelvärdet används som känslighetsinformation och styr inte den publicerade prioriteringen.</p></details>`;
}
function measurementEmpty(title,text='Figuren visas när giltiga resultat för denna analys har införts.') {
  return `<div class="ms-empty"><span class="ms-status">Inväntar underlag</span><h3>${esc(title)}</h3><p>${esc(text)}</p></div>`;
}
function measurementDistribution(distribution,label,selected=null) {
  if(!distribution)return measurementEmpty('Förlustfördelning saknas','En monetär Monte Carlo-fördelning behövs. Separata sannolikhets- eller konsekvensdragningar räcker inte.');
  const bins=distribution.bins,max=Math.max(...bins.map(b=>b.count/distribution.sampleCount),0.01),width=680,height=250,left=58,top=18,plotW=600,plotH=180;
  const min=bins[0].lower,maxX=bins.at(-1).upper,span=maxX-min||1;
  const x=v=>left+(v-min)/span*plotW,y=v=>top+plotH-v/max*plotH;
  const selectedMarker=selected&&selected.value>=min&&selected.value<=maxX?`<line class="ms-statistic-marker" x1="${x(selected.value)}" x2="${x(selected.value)}" y1="${top}" y2="${top+plotH}" stroke="#1f272f" stroke-width="2"><title>${RISK_STATISTIC_LABEL}: ${measurementMoney(selected.value)}</title></line>`:'';
  return `<figure class="ms-histogram"><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${esc(label)}. ${distribution.sampleCount} simulerade utfall. P50 ${measurementMoney(distribution.p50)}, P95 ${measurementMoney(distribution.p95)}."><title>${esc(label)}</title>${[0,.5,1].map(f=>`<line x1="${left}" x2="${left+plotW}" y1="${y(f*max)}" y2="${y(f*max)}" stroke="#dfe4e7"/><text x="${left-9}" y="${y(f*max)+4}" text-anchor="end">${measurementNumber(f*max*100)} %</text>`).join('')}${bins.map(b=>`<rect x="${x(b.lower)}" y="${y(b.count/distribution.sampleCount)}" width="${Math.max(2,(b.upper-b.lower)/span*plotW-2)}" height="${top+plotH-y(b.count/distribution.sampleCount)}" fill="#1d6362"><title>${measurementMoney(b.lower)}–${measurementMoney(b.upper)}: ${measurementNumber(b.count/distribution.sampleCount*100)} %</title></rect>`).join('')}<line x1="${x(distribution.p95)}" x2="${x(distribution.p95)}" y1="${top}" y2="${top+plotH}" stroke="#d57e05" stroke-dasharray="5 4"/>${selectedMarker}${[0,.25,.5,.75,1].map(f=>`<text x="${left+f*plotW}" y="${top+plotH+22}" text-anchor="middle">${measurementNumber((min+f*span)/1e6)}</text>`).join('')}<text x="${left+plotW/2}" y="244" text-anchor="middle">Förlust under ${measurementPeriod()}, ${measurementCurrencyUnit()}</text></svg><figcaption>Ursprung: exporterad modellsimulering · Mått: andel simulerade utfall · ${measurementNumber(distribution.sampleCount)} utfall · Run ${esc(distribution.runId)}</figcaption><div class="ms-quantiles">${selected?`<span class="ms-selected-statistic">Visat mått · ${RISK_STATISTIC_LABEL}<strong>${measurementMoney(selected.value)}</strong></span>`:''}${selected&&RISK_STATISTIC==='median'?'':`<span>Median (P50)<strong>${measurementMoney(distribution.p50)}</strong></span>`}<span>P95<strong>${measurementMoney(distribution.p95)}</strong></span></div><details class="ms-data-table"><summary>Visa figurens data</summary><table class="ex-table"><thead><tr><th>Modellförlust från</th><th>Modellförlust till</th><th>Antal simulerade utfall</th></tr></thead><tbody>${bins.map(b=>`<tr><td>${measurementMoney(b.lower)}</td><td>${measurementMoney(b.upper)}</td><td>${measurementNumber(b.count)}</td></tr>`).join('')}</tbody></table></details></figure>`;
}
function measurementBars(rows,{emptyTitle='Bidrag till förväntad förlust',button=true}={}) {
  if(!rows.length)return measurementEmpty(emptyTitle);
  const max=Math.max(...rows.map(r=>Math.abs(r.value)),1);
  return `<div class="ms-bars">${rows.map((r,i)=>`<div class="ms-bar-row">${button&&r.riskId?`<button class="ex-text-link" data-ex-risk="${esc(r.riskId)}" data-ex-risk-tab="analysis">${esc(r.label)}</button>`:`<span>${esc(r.label)}</span>`}<div class="ms-bar-track"><span class="${i===0?'ms-bar-first':''}" style="width:${Math.abs(r.value)/max*100}%"></span></div><div class="ms-bar-value"><strong>${measurementMoney(r.value)}</strong>${r.riskId?measurementProvenanceLabel(r.riskId,'expectedLoss'):r.provenance?`<small>${esc(r.provenance)}</small>`:''}</div></div>`).join('')}</div>`;
}
function measurementRange(value) {
  const range=measurementNumber(value.lower/(value.unit==='SEK_per_event'?1e6:1))+'–'+measurementNumber(value.upper/(value.unit==='SEK_per_event'?1e6:1));
  return range+(value.unit==='SEK_per_event'?' mnkr / händelse':value.unit==='events_in_period'?' händelser under perioden':' händelser / år');
}
function measurementDescriptionReview(id) {
  if(REVIEWED_COST&&MEASUREMENT.byRisk.get(id)?.sourceReview)return '';
  const review=MEASUREMENT.byRisk.get(id)?.descriptionReview;if(!review)return '';
  const range=e=>`<article class="ms-description-range"><h4>${e.dimension==='likelihood'?'Händelsefrekvens':'Kostnad vid händelse'}</h4><strong>${measurementRange(e)}</strong><p>${esc(e.scope)}${e.qualification?(/[.!?]$/.test(e.scope)?' ':'. ')+esc(e.qualification):''}</p><details><summary>Läs uppgiften i riskbeskrivningen</summary><blockquote>${esc(e.sourceQuote)}</blockquote><p class="ex-note">Källa: den frysta riskbeskrivningen som låg till grund för riskbedömningen. Uppgiften återges som en beskrivningsskattning och har inte verifierats som observerad statistik.</p></details></article>`;
  return `<section class="ms-panel ms-description-review"><h3>${review.estimates.length?'Återvunna värden ur riskbeskrivningen':'Genomgång av riskbeskrivningen'}</h3>${review.estimates.length?`<p>Intervallen anger storleksordningar i källtexten. De har ingen fastställd median eller medelkostnad och används inte för beräkning av förväntad årskostnad.</p><div class="ms-analysis-grid">${review.estimates.map(range).join('')}</div>`:''}<p>${esc(review.assessment)}</p>${review.contextValues.length?`<details><summary>Uppgifter för en annan period eller avgränsning</summary><p>Dessa värden används endast som bakgrund och ersätter inte riskens årliga frekvens.</p>${review.contextValues.map(range).join('')}</details>`:''}${review.missing.length?`<h4>Vad som saknas för årskostnaden</h4>${review.missing.map(m=>`<p>${esc(m.reason)}</p>`).join('')}`:`<p>För denna risk används modellmedianer i indikatorn. Beskrivningens uppgifter ger kompletterande sammanhang och har inte använts som numeriska ersättningsvärden.</p>`}<a class="ex-text-link" href="data/description-review.json">Hela genomgången och källhänvisningarna (JSON)</a></section>`;
}
function measurementSanitySummary(id) {
 const row=MEASUREMENT.byRisk.get(id),r=row?.sourceReview,audit=measurementAudit(id),h=(r?.history||[]).find(h=>h.sourceUrl);
 const level=measurementReviewLevel(id);
 const fallback=row&&row.qualityStatus!=='outside_execution'?'Den publicerade beräkningen och uppgifternas ursprung har kontrollerats. Denna risk ingår inte i den fördjupade granskningen av 80 risker, och värdena har därför inte verifierats mot jämförbar historisk frekvens eller projektkostnad. Modellvärdena behålls som bedömningar tills sådana uppgifter finns.':'Risken ingick inte i mätningen och saknar underlag för frekvens, kostnad och rangordning. Den finns kvar i registret, men någon jämförelse av den numeriska nivån mot historiska utfall kan ännu inte göras.';
 const assessment=audit?.sanityAssessment||r?.sanityAssessment||r?.reason||fallback;
 const question=audit?.openQuestion||r?.openQuestion||(!r&&row?.qualityStatus!=='outside_execution'?'Jämförbar historik om riskens faktiska händelser per år och ekonomiska konsekvens per händelse behövs för att pröva modellens nivåer.':null);
 return `<aside class="ms-quality-note ms-sanity" data-sanity-risk="${esc(id)}"><h3>Rimlighetsbedömning</h3><p class="ms-review-scope">Granskningsnivå: ${esc(level)}. ${r?'Källjämförelsen innebär inte att kostnaden är historiskt validerad.':'Ingen fördjupad historisk validering.'}</p><p>${esc(assessment)}</p>${question?`<p><strong>Kvar att klarlägga:</strong> ${esc(question)}</p>`:''}${!primaryCost(row)?`<p><strong>Värdet saknas eftersom:</strong> ${esc(measurementMissingReason(id))}</p>`:''}${h?`<a href="${esc(h.sourceUrl)}" target="_blank" rel="noopener noreferrer">${esc(h.sourceTitle||'Historisk källa')}</a>`:''}</aside>`;
}
function measurementSourceReview(row) {
 const r=row.sourceReview,link=h=>h.sourceUrl?` <a href="${esc(h.sourceUrl)}" target="_blank" rel="noopener noreferrer">${esc(h.sourceTitle||'Källa')}</a>`:'';
 const dimension=d=>{const x=r[d],v=row.reviewedInputs[d];if(!x)return '';const title=d==='likelihood'?'Händelsefrekvens':'Kostnad per händelse';const format=n=>d==='likelihood'?measurementNumber(n)+' händelser/år':measurementMoney(n);return `<article class="ms-panel"><h4>${title}</h4><p>Ursprunglig modellmedian: <strong>${format(x.model)}</strong>.</p>${v&&v.method!=='model_median'?`<p>Källintervall: <strong>${format(v.lower)}–${format(v.upper)}</strong>. Använt jämförelsevärde: <strong>${format(v.value)}</strong> (${v.method==='source_range_midpoint'?'aritmetisk mittpunkt':'källuppgift'}).</p><p>${esc(v.scope)}. ${esc(v.qualification||'')}</p>`:v?'<p>Modellmedianen behålls efter jämförelsen.</p>':'<p><strong>Odefinierat efter granskning.</strong></p>'}${x.sourceQuote?`<details><summary>Läs källuppgiften</summary><blockquote>${esc(x.sourceQuote)}</blockquote><p>${esc(x.sourceTitle||'Fryst riskbeskrivning till mätningen')}${link(x)}</p></details>`:''}</article>`;};
 return `<section class="ms-panel"><h3>Källgranskning och använda värden</h3>${r.sanityAssessment?`<p>${esc(r.reason)}</p>`:''}<div class="ms-analysis-grid">${dimension('likelihood')}${dimension('impact')}</div>${r.history?.length?`<details><summary>Historiska uppgifter och jämförbarhet</summary>${r.history.map(h=>`<p>${esc(h.finding||h.description||h.reason||'')}${link(h)}</p>`).join('')}</details>`:''}<p class="ex-note">Beskrivningsskattningar är bedömningar i källtexten. Att ett intervall används gör inte mittpunkten till en observerad kostnad eller en statistisk median.</p><a href="data/source-review.json">Hela granskningen med källor och beslut (JSON)</a></section>`;
}
function measurementReview(id) {
  const row=MEASUREMENT.byRisk.get(id),flags=row?.review||[];
  if(REVIEWED_COST&&row?.sourceReview)return measurementSourceReview(row);
  if(CENTRAL_COST&&row?.centralCost){const notes=(row.distributionNotes||[]).filter(n=>n.code==='description_range_tension');return notes.length?`<aside class="ms-quality-note"><strong>Storleksordningen behöver granskas</strong>${notes.map(n=>`<p>${esc(n.reason)}${n.sourceUrl?` <a href="${esc(n.sourceUrl)}" target="_blank" rel="noopener noreferrer">${esc(n.sourceTitle||'Källa')}</a>`:''}</p>`).join('')}</aside>`:'';}
  if(row?.descriptionReview&&row.expectedLoss)return '';
  if(row?.descriptionReview)return `<aside class="ms-quality-note"><strong>Kostnadsunderlaget är odefinierat efter granskning</strong><p>${row.descriptionReview.estimates.length?'Intervall har återvunnits ur riskbeskrivningen och redovisas i analysen. En kvarstående brist i skala, population eller kalibrering hindrar beräkningen av årskostnad.':'Riskbeskrivningen ger inget jämförbart numeriskt intervall som kan fylla de saknade centralmåtten.'}</p><details><summary>Varför modellvärdet inte används</summary>${flags.map(f=>`<p>${esc(f.reason)}</p>`).join('')}</details><a href="?view=report&chapter=bilaga-kvalitet">Granskning av värden och beskrivningar</a></aside>`;
  return flags.length?`<aside class="ms-quality-note"><strong>Underlag saknas</strong>${flags.map(f=>`<p>${esc(f.reason)}</p>`).join('')}<a href="?view=report&chapter=bilaga-kvalitet">Granskningsregler och metod</a></aside>`:'';
}
function measurementQuantilePanel(id,dimension) {
  const row=MEASUREMENT.byRisk.get(id),summary=row?.summaries?.[dimension];
  const title=dimension==='likelihood'?'Osäkerhet om årlig frekvens':'Osäkerhet om kostnad per händelse';
  if(!summary)return `<section class="ms-panel"><h3>${title}</h3><p>Värdet är odefinierat efter utgåvans granskning. Ursprungliga medelvärden och medianer finns bevarade i källdata.</p></section>`;
  const low=summary.quantiles?.p5??summary.quantiles?.p05??summary.interval90?.[0],high=summary.quantiles?.p95??summary.interval90?.[1],median=summary.median,mean=summary.mean;
  const fmt=v=>v==null?'Ej definierat':dimension==='likelihood'?measurementNumber(v)+' / år':measurementMoney(v);
  const x=v=>30+560*(Math.log10(Math.max(v,1e-10))-Math.log10(Math.max(low,1e-10)))/(Math.log10(high)-Math.log10(Math.max(low,1e-10))||1);
  return `<section class="ms-panel"><h3>${title}</h3><svg class="ms-interval" viewBox="0 0 620 120" role="img" aria-label="P5 ${esc(fmt(low))}, median ${esc(fmt(median))}, P95 ${esc(fmt(high))}. Logaritmisk skala."><line x1="30" y1="40" x2="590" y2="40" stroke="#cbd5d9" stroke-width="8"/><line x1="30" y1="28" x2="30" y2="52" stroke="#1d6362" stroke-width="2"/><line x1="590" y1="28" x2="590" y2="52" stroke="#1d6362" stroke-width="2"/><circle cx="${x(median)}" cy="40" r="7" fill="#1d6362"/>${mean!=null&&mean>=low&&mean<=high?`<line x1="${x(mean)}" y1="25" x2="${x(mean)}" y2="55" stroke="#c56e00" stroke-width="3"/>`:''}<text x="30" y="85">P5 ${fmt(low)}</text><text x="590" y="85" text-anchor="end">P95 ${fmt(high)}</text></svg><div class="ms-quantiles"><span>Mätresultat · modellmedian (P50)<strong>${fmt(median)}</strong></span><span>Mätresultat · modellmedelvärde<strong>${fmt(mean)}</strong></span></div><p class="ex-note">Ursprung: mätresultat från den ursprungliga modellen. Mått: modellens P5, median och P95, med medelvärdet separat. Dessa ursprungsvärden ändras inte när publiceringens jämförelsevärden justeras. Logaritmisk skala. Grön punkt visar median; orange streck visar medelvärde. ${dimension==='likelihood'?(DATA.measurement.provenance.controlBasis==='inherent_no_controls'?'Kvantiler härledda ur den kalibrerade frekvensfördelningen utan införda åtgärder. Ingen ny simulering.':'Kvantiler från exporterade Monte Carlo-dragningar av frekvensparametern.'):'Kvantiler härledda ur den kalibrerade lognormalfördelningen för medelkostnaden per händelse.'}</p></section>`;
}
function measurementRiskAnalysis(risk) {
  const row=MEASUREMENT.byRisk.get(risk.risk_id);
  return `${measurementSanitySummary(risk.risk_id)}${measurementDescriptionReview(risk.risk_id)}${measurementReview(risk.risk_id)}<details class="ex-method ms-uncertainty"><summary>Fördjupning: osäkerhet i frekvens och kostnad</summary><p>Intervallen beskriver modellens osäkerhet om parametrarna. De visar inte variationen i faktiska projektkostnader.</p><div class="ms-analysis-grid">${measurementQuantilePanel(risk.risk_id,'likelihood')}${measurementQuantilePanel(risk.risk_id,'impact')}</div></details><section class="ms-panel"><h3>${RISK_LOSS_LABEL}</h3>${measurementFormula(risk.risk_id)}<p class="ex-note">Mätunderlaget innehåller separata fördelningar för frekvens och konsekvens. En gemensam monetär årsförlustfördelning finns inte i exporten, så årsförlustens median och P95 lämnas odefinierade.</p></section><details class="ex-method"><summary>Källvärden, mätkälla och beräkning</summary><p>Källvärdena bevaras även när publiceringsreglerna har uteslutit dem från beräkning och rangordning. Impact Monte Carlo har ett separat diagnostiskt medelvärde som inte används som medelkostnad i årskostnaden.</p><div class="ex-table-wrap"><table class="ex-table"><thead><tr><th>Källmått · ursprunglig modellmätning</th><th>Median (P50)</th><th>Medelvärde</th></tr></thead><tbody>${Object.entries(row?.sourceStatistics||{}).filter(([k,v])=>v&&['likelihood','impactBelief','impactMonteCarloDiagnostic'].includes(k)).map(([k,v])=>`<tr><td>${({likelihood:'Frekvens utan kontroller · händelser/år',impactBelief:'Kostnadsbedömning · mnkr/händelse',impactMonteCarloDiagnostic:'Separat MC-diagnostik med kontroller · mnkr'})[k]}</td><td>${k==='likelihood'?measurementNumber(v.median):measurementMoney(v.median)}</td><td>${k==='likelihood'?measurementNumber(v.mean):measurementMoney(v.mean)}</td></tr>`).join('')}</tbody></table></div>${measurementProvenance(row)}</details><button class="btn ms-teal" data-ex-risk="${esc(risk.risk_id)}" data-ex-risk-tab="controls">Visa riskens motåtgärder</button>`;
}
function measurementProvenance(row) {
  const p=DATA.measurement.provenance;
  if(!p)return '<p class="ex-note">Den tidigare BTL-rangordningen är fortfarande synlig. Absoluta mått för den nya utgåvan inväntas.</p>';
  return `<dl class="ex-facts"><dt>Mätutgåva</dt><dd>${esc(DATA.measurement.editionId)}</dd><dt>Execution</dt><dd class="ex-mono">${esc(p.executionId)}</dd><dt>Period / valuta</dt><dd>${measurementPeriod()} · ${esc(p.currency)}</dd><dt>Avgränsning</dt><dd>${esc(p.scope.description)}</dd><dt>Exponeringsbas</dt><dd>${esc(p.scope.exposureBasis)}</dd>${row?Object.entries(row.summaries||{}).map(([key,summary])=>`<dt>${({likelihood:'Händelsemått',impact:'Konsekvens',expectedLoss:'Förlust'})[key]} · median/medelvärde</dt><dd>Run <span class="ex-mono">${esc(summary.runId)}</span> · ${esc(summary.definition)}</dd>`).join(''):''}${row?['likelihood','impact','expectedLoss','lossDistribution'].filter(k=>row[k]).map(k=>`<dt>${({likelihood:'Händelsemått',impact:'Konsekvens',expectedLoss:'Förlust',lossDistribution:'Monte Carlo'})[k]}</dt><dd>Run <span class="ex-mono">${esc(row[k].runId)}</span>${row[k].calibrationStatus?` · ${esc(row[k].calibrationStatus)} (modellkalibrering)` :''}</dd>`).join(''):''}</dl><a class="ref" href="data/measurement.json">Visningsdata och körningsreferenser (JSON)</a>`;
}
function measurementControlDetail(control) {
  const effects=MEASUREMENT.byControl.get(control.id)?.effects||[];
  const investment=evaluateInvestment(DATA.measurement,EX_DATA.controls,[control.id]);
  if(investment)return `<section class="ms-panel"><h3>Föreslagen investering</h3>${measurementControlProvenance()}<p>Åtgärden är ännu inte införd. Modellen beräknar en potentiell minskning av kostnadsindikatorn på <strong>${measurementMoney(investment.reduction)} per år</strong> för ${investment.pricedCount} av ${investment.affectedCount} kopplade riskposter. Beloppet förutsätter att åtgärden införs ensam; överlappande ekonomiska förluster har inte räknats bort.</p><p>Genomförandekostnad: ej angiven. ${investment.adverseCount?`${investment.adverseCount} ${investment.adverseCount===1?'risk får':'risker får'} ökad kostnad i modellen och behöver granskas.`:''}</p><button class="btn ms-teal" data-pub-analyse-control="${esc(control.id)}">Undersök bidrag och kombinationer</button></section>`;
  return `<section class="ms-panel"><h3>Kontrollens effektanalys</h3><p>${effects.length?`${effects.length} resultatposter på latent modellskala har införts. De är inte procentuell kostnadsreduktion.`:'Effektresultat för denna kontroll inväntas. Riskkopplingarna finns redan tillgängliga.'}</p><button class="btn ms-teal" data-pub-analyse-control="${esc(control.id)}">Undersök i kontrollernas Analys-flik</button>${effects.length?`<details class="ex-method"><summary>Resultat på modellskala och källstatus</summary><table class="ex-table"><thead><tr><th>Risk</th><th>Dimension</th><th>Delta (latent)</th><th>Status</th><th>Run</th></tr></thead><tbody>${effects.map(e=>`<tr><td><button class="ex-text-link" data-ex-risk="${esc(e.riskId)}" data-ex-risk-tab="analysis">${esc(e.riskId)}</button></td><td>${e.dimension==='likelihood'?'Händelsemått':'Konsekvens'}</td><td>${measurementNumber(e.delta)}</td><td>${esc(e.status)}</td><td class="ex-mono">${esc(e.runId)}</td></tr>`).join('')}</tbody></table></details>`:''}</section>`;
}
function measurementAggregateRows() {
  return RISKS.filter(r=>(!publicationState.analysisChart||r.chart_key===publicationState.analysisChart)&&(!publicationState.analysisTop||RANKING.topRiskIds.has(r.risk_id)));
}
function measurementScatter(risks) {
  const rows=risks.map(r=>({r,x:riskMetric(r.risk_id,'likelihood')?.value,y:riskMetric(r.risk_id,'impact')?.value})).filter(v=>v.x>0&&v.y>0);
  if(!rows.length)return '<p>Inga jämförbara mått finns i urvalet.</p>';
  const minX=Math.floor(Math.log10(Math.min(...rows.map(r=>r.x)))),maxX=Math.ceil(Math.log10(Math.max(...rows.map(r=>r.x))));
  const minY=Math.floor(Math.log10(Math.min(...rows.map(r=>r.y)))),maxY=Math.ceil(Math.log10(Math.max(...rows.map(r=>r.y))));
  const x=v=>70+(Math.log10(v)-minX)/(maxX-minX||1)*590,y=v=>310-(Math.log10(v)-minY)/(maxY-minY||1)*275;
  return `<svg class="ms-scatter" viewBox="0 0 710 365" role="img" aria-label="Risker efter frekvens och kostnad per händelse. Logaritmiska axlar. Orange visar kostnadstopp 50.">${Array.from({length:maxX-minX+1},(_,i)=>minX+i).map(v=>`<line x1="${x(10**v)}" x2="${x(10**v)}" y1="35" y2="310" stroke="#dfe4e7"/><text x="${x(10**v)}" y="333" text-anchor="middle">${measurementNumber(10**v)}</text>`).join('')}${Array.from({length:maxY-minY+1},(_,i)=>minY+i).map(v=>`<line x1="70" x2="660" y1="${y(10**v)}" y2="${y(10**v)}" stroke="#dfe4e7"/><text x="62" y="${y(10**v)+4}" text-anchor="end">${measurementNumber(10**v/1e6)}</text>`).join('')}${rows.map(({r,x:vx,y:vy})=>`<a href="?risk=${encodeURIComponent(r.risk_id)}&tab=analysis" aria-label="${esc(r.title)}"><circle cx="${x(vx)}" cy="${y(vy)}" r="5" fill="${RANKING.topRiskIds.has(r.risk_id)?'#df830c':'#1d6362'}" opacity=".8"><title>${esc(r.title)} · ${measurementNumber(vx)} händelser/år (${esc(measurementProvenanceMeta(r.risk_id,'likelihood').label)}) · ${measurementMoney(vy)} per händelse (${esc(measurementProvenanceMeta(r.risk_id,'impact').label)})</title></circle></a>`).join('')}<text x="365" y="360" text-anchor="middle">Händelser per år · ${REVIEWED_COST?'granskat värde':RISK_STATISTIC==='median'?'median':'medelvärde'}</text><text x="70" y="18">Kostnad per händelse, mnkr</text></svg><p class="ex-note">${rows.length} risker har båda måtten. Båda axlarna är logaritmiska. Orange markerar kostnadstopp 50; klicka på en punkt för riskanalysen. Ursprung och statistiskt mått anges för båda koordinaterna i punktens titel och på riskkortet: modellmedian eller beskrivningsskattningens aritmetiska mittpunkt.</p>`;
}
function renderRiskAnalysis() {
  const risks=measurementAggregateRows(),rows=risks.map(r=>({riskId:r.risk_id,label:r.title,value:primaryCost(MEASUREMENT.byRisk.get(r.risk_id))?.value})).filter(r=>r.value!=null).sort((a,b)=>b.value-a.value),sum=rows.reduce((s,r)=>s+r.value,0);
  const processes=CHARTS.map(key=>{const all=risks.filter(r=>r.chart_key===key),priced=all.filter(r=>primaryCost(MEASUREMENT.byRisk.get(r.risk_id)));return {key,total:all.length,count:priced.length,top:all.filter(r=>RANKING.topRiskIds.has(r.risk_id)).length,value:priced.reduce((s,r)=>s+primaryCost(MEASUREMENT.byRisk.get(r.risk_id)).value,0)};}).filter(p=>p.total);
  $('#main').innerHTML=`<div class="ex-page-head"><div><div class="eyebrow">Riskanalys · oktober 2026</div><h2>Kostnad, frekvens och berörda processer</h2><p>Jämför riskernas storlek och följ hur prioriteringen fördelar sig över processen.</p></div><button class="btn" data-pub-controls-analysis>Motåtgärdernas analys</button></div>${measurementModeNote()}${measurementScope('mean')}${measurementAggregateNote(risks.map(r=>r.risk_id))}<div class="ms-filter-row"><label>Process <select id="msAnalysisChart"><option value="">Alla processer</option>${CHARTS.map(c=>`<option value="${c}" ${publicationState.analysisChart===c?'selected':''}>${esc(c+' · '+CHART_NAME[c])}</option>`).join('')}</select></label><label class="ex-check"><input id="msAnalysisTop" type="checkbox" ${publicationState.analysisTop?'checked':''}> Endast kostnadstopp 50</label></div><div class="ms-metrics"><div><span>Risker med kostnadsunderlag</span><strong>${rows.length} / ${risks.length}</strong><small>${risks.length-rows.length} saknar granskad indikator</small></div><div><span>Summa separata riskposter</span><strong>${rows.length?measurementMoney(sum):'Ej definierat'}</strong><small>Granskade indikatorer · separata poster</small></div><div><span>Samlad årsförlust · median</span><strong>Ej definierad</strong><small>Gemensam förlustfördelning saknas</small></div></div><aside class="ms-quality-note"><p>Summan avser beräknade indikatorer från de redovisade modell- och källuppgifterna för separata riskposter. Samma projektkostnad kan förekomma i flera risker och alternativa processvägar. Beloppet kan därför inte tolkas som Sveriges samlade kostnad. Utelämnade värden räknas inte som noll.</p></aside><section class="ms-panel"><h3>Högst granskad kostnadsindikator i urvalet</h3>${measurementBars(rows.slice(0,8))}</section><details class="ex-method"><summary>Fördjupning: jämför frekvens och kostnad per händelse</summary>${measurementScatter(risks)}</details><section class="ms-panel"><h3>Riskbild per delprocess</h3><div class="ex-table-wrap"><table class="ex-table"><thead><tr><th>Process</th><th>Kostnadsunderlag</th><th>Topp 50</th><th>Summa separata riskposter / år</th></tr></thead><tbody>${processes.map(p=>`<tr><td><button class="ex-text-link" data-open-process="${p.key}">${esc(CHART_NAME[p.key])}</button></td><td>${p.count} / ${p.total}</td><td><span class="ms-count-bar" style="width:${p.top*4}px"></span>${p.top}</td><td>${p.count?measurementMoney(p.value):'Ej definierat'}</td></tr>`).join('')}</tbody></table></div><p class="ex-note">Varje risk hänförs till sin direkta processnod. Följdpåverkan visas i processkartorna utan att kostnaden kopieras till ytterligare processer.</p></section><details class="ex-method"><summary>Granskning, avgränsning och källor</summary><p>${esc(DATA.measurement.quality?.note||'')}</p><a href="?view=report&chapter=bilaga-metod">Metod och avgränsningar i bilagan</a>${measurementProvenance()}</details>`;
  $('#msAnalysisChart').onchange=e=>{publicationState.analysisChart=e.target.value;renderRiskAnalysis();exSyncRoute();};$('#msAnalysisTop').onchange=e=>{publicationState.analysisTop=e.target.checked;renderRiskAnalysis();exSyncRoute();};bindRankingLinks($('#main'));
}
function measurementControlTabs() {
  return ''; // Section navigation is rendered once in the shared header.
}
function measurementScenarioFigure(s) {
  if(!s)return measurementEmpty('Effekt på riskkostnaden','En exporterad scenarioberäkning för exakt de valda kontrollerna behövs. Latenta effekter summeras inte till en kostnadsreduktion.');
  const max=Math.max(s.referenceExpectedLoss,s.residualExpectedLoss,1);
  return `<figure class="ms-scenario-figure"><div class="ms-scenario-bars">${[['Referens',s.referenceExpectedLoss],['Med valda åtgärder',s.residualExpectedLoss]].map(([label,value],i)=>`<div><strong>${measurementMoney(value)}</strong><div class="ms-scenario-column ${i?'residual':''}" style="height:${Math.max(0,value/max*170)}px"></div><span>${label}</span></div>`).join('')}</div><figcaption>Ursprung: exporterad scenariomodell. Mått: beräknat årligt medelvärde i ursprunglig modell · ${esc(s.title||s.id)} · ${measurementPeriod()} · Run ${esc(s.runId)}</figcaption></figure>${s.contributions?.length?`<h4>Bidrag i det exporterade scenariot</h4>${measurementBars(s.contributions.map(c=>({label:EX_CONTROLS.get(c.controlId)?.title||c.controlId,value:c.reduction,provenance:'Exporterat modellresultat · beräknad medelvärdesdifferens'})),{button:false})}`:''}<p class="ex-note">${esc(s.method)} · Överlapp: ${esc(s.overlapTreatment)}</p>`;
}
function measurementImportedControlAnalysis(visibleControls) {
  const analysis=DATA.measurement.controlAnalysis;
  if(!analysis)return `<section class="ms-panel"><h3>Åtgärdernas räckvidd i riskbilden</h3><p>Mätunderlaget innehåller ${DATA.measurement.controls?.reduce((n,c)=>n+c.effects.length,0)||0} effektposter på modellskala. Monetär reduktion och kostnad för genomförande saknar validerat underlag. Tabellen visar dokumenterade samband, med kostnadstopp 50 som en av flera prioriteringsgrunder.</p><div class="ex-table-wrap"><table class="ex-table"><thead><tr><th>Motåtgärd</th><th>Kopplade risker</th><th>I topp 50</th><th>Med kostnadsunderlag</th><th>Effektposter</th></tr></thead><tbody>${[...visibleControls].sort((a,b)=>b.riskIds.length-a.riskIds.length).slice(0,20).map(c=>`<tr><td><button class="ex-text-link" data-ex-control="${esc(c.id)}">${esc(c.title)}</button></td><td>${c.riskIds.length}</td><td>${c.riskIds.filter(id=>RANKING.topRiskIds.has(id)).length}</td><td>${c.riskIds.filter(id=>primaryCost(MEASUREMENT.byRisk.get(id))).length}</td><td>${MEASUREMENT.byControl.get(c.id)?.effects.length||0}</td></tr>`).join('')}</tbody></table></div></section>`;
  const visible=new Set(visibleControls.map(c=>c.id));
  const rows=analysis.controls.filter(c=>visible.has(c.controlId)).sort((a,b)=>(b.attributedReduction??-1)-(a.attributedReduction??-1));
  return `<section class="ms-panel"><h3>Kontrollanalys från Cardinal</h3><p class="ex-note">Ursprung: exporterad kontrollmodell. Mått: beräknat årligt medelvärde i det ursprungliga mätunderlaget; källjusterade basvärden ingår inte här. Hela mätningens riskurval. Fördelade bidrag beskriver den exporterade kontrollanalysen; effekten av ett nytt kontrollurval kräver ett eget scenario.</p><div class="ms-metrics"><div><span>Risk utan kontroller</span><strong>${measurementMoney(analysis.inherentExpectedLoss)}</strong></div><div><span>Kvarvarande risk</span><strong>${measurementMoney(analysis.residualExpectedLoss)}</strong></div><div><span>Fördelad riskreduktion</span><strong>${measurementMoney(analysis.totalAttributedReduction)}</strong></div></div><details class="ms-data-table"><summary>Visa bidrag för åtgärder i aktuellt filter (${rows.length})</summary><div class="ex-table-wrap"><table class="ex-table"><thead><tr><th>Motåtgärd</th><th>Fördelat bidrag · medelvärde</th><th>Risker med modellerad effekt</th><th>Årlig kostnad</th></tr></thead><tbody>${rows.map(c=>`<tr><td><button class="ex-text-link" data-ex-control="${esc(c.controlId)}">${esc(EX_CONTROLS.get(c.controlId)?.title||c.controlId)}</button></td><td>${measurementMoney(c.attributedReduction)}</td><td>${measurementNumber(c.risksWithMeasuredEffect)}</td><td>${c.costStatus==='known'?measurementMoney(c.annualCost):'Ej angiven'}</td></tr>`).join('')}</tbody></table></div></details></section>`;
}
function investmentPercent(value) {return value==null?'—':`${measurementNumber(value*100)} %`;}
function investmentScaleNotes(ids) {return REVIEWED_COST?[]:ids.filter(id=>(MEASUREMENT.byRisk.get(id)?.distributionNotes||[]).some(n=>n.code==='description_range_tension'));}
function investmentMethod() {return `<details class="ex-method"><summary>Så beräknas åtgärdernas bidrag</summary><p>Jämförelsen börjar utan införda motåtgärder. Kostnadsindikatorn beräknas från granskade källuppgifter och kvarvarande modellmedianer. Intervall använder aritmetisk mittpunkt. Kontrollerna tillämpas som modellberäknade relativa effekter även på justerade basvärden; deras effekt har inte mätts om eller verifierats empiriskt. För varje risk används mätningens fördelade effekter på frekvens och kostnad per händelse. Effekterna flyttar modellens logaritmiska skala; omräkningen till kronor görs därefter. Osäkerhetens bredd hålls konstant.</p><p>Flera valda åtgärders effekter kombineras per risk innan kostnaden beräknas. Enskilda besparingar adderas inte. Modellen skattar inga särskilda samspel mellan åtgärder. Negativa resultat behålls och betyder att modellen förutsäger en ökning, vilket behöver granskas.</p><p>Beloppen är summor av separata riskposter i det angivna urvalet. Samma ekonomiska förlust kan förekomma i flera risker, så summan är ett jämförelseunderlag och ingen nationell nettobesparing. Ingen genomförandekostnad eller uppmätt effekt efter införande finns. Beräkningen återanvänder mätresultaten utan att starta en ny mätning.</p></details>`;}
function investmentSelection(s) {
  if(!s?.selectedIds.length)return `<section class="ms-panel"><h3>Undersök en investering</h3><p>Markera en eller flera föreslagna åtgärder. Här visas förändringen för varje berörd risk och ett samlat jämförelsebelopp för de risker som har kostnadsunderlag.</p></section>`;
  const max=Math.max(s.referenceExpectedLoss||0,s.residualExpectedLoss||0,1);
  return `<section class="ms-panel"><div class="eyebrow">${s.selectedIds.length} ${s.selectedIds.length===1?'föreslagen åtgärd':'föreslagna åtgärder'}</div><h3>Potentiell riskreduktion i ditt urval</h3>${measurementControlProvenance()}<p>${s.pricedCount} av ${s.affectedCount} berörda risker kan jämföras i kronor. ${s.unknownCount?`${s.unknownCount} saknar jämförbar kostnadsindikator eller effektunderlag.`:''}</p>${investmentScaleNotes(s.rows.map(r=>r.riskId)).length?`<aside class="ms-quality-note"><strong>Kostnadsnivåerna behöver granskas</strong><p>Urvalet innehåller ${investmentScaleNotes(s.rows.map(r=>r.riskId)).length} ${investmentScaleNotes(s.rows.map(r=>r.riskId)).length===1?'riskpost':'riskposter'} där modellkostnaden avviker tydligt från beskrivningens bedömningsram. Kontrollera dessa underlag innan beloppen används för investeringsbeslut: ${investmentScaleNotes(s.rows.map(r=>r.riskId)).map(id=>exRiskButton(EX_RISKS.get(id))).join(', ')}.</p></aside>`:''}<div class="ms-metrics ms-control-metrics"><div><span>Beräknad modellpotential / år</span><strong>${measurementMoney(s.reduction)}</strong><small>Beräknad modellpotential · korrigerad bas</small></div><div><span>Förändring av samma riskposter</span><strong>${investmentPercent(s.reductionFraction)}</strong><small>${s.adverseCount?`${s.adverseCount} ${s.adverseCount===1?'risk får':'risker får'} ökad modellkostnad`:'Modellberäknad potential'}</small></div><div><span>Genomförandekostnad</span><strong>Ej angiven</strong><small>Behövs för investeringsbeslut</small></div><div><span>Nettonytta</span><strong>Ej beräknad</strong><small>Kostnad och ekonomiska överlapp återstår</small></div></div>${s.pricedCount?`<figure class="ms-scenario-figure"><div class="ms-scenario-bars">${[['Utan införda åtgärder',s.referenceExpectedLoss],['Med ditt åtgärdsurval',s.residualExpectedLoss]].map(([label,v],i)=>`<div><strong>${measurementMoney(v)}</strong><div class="ms-scenario-column ${i?'residual':''}" style="height:${Math.max(0,v/max*170)}px"></div><span>${label}</span></div>`).join('')}</div><figcaption>Ursprung: kontrollmodell och granskade basvärden. Mått: beräknad indikator för samma ${s.pricedCount} riskposter. Ekonomiska överlapp har inte räknats bort.</figcaption></figure>`:''}<div class="ex-table-wrap"><table class="ex-table"><caption>Modellberäknad förändring per risk vid föreslaget införande</caption><thead><tr><th>Risk</th><th>Modellerad frekvensminskning</th><th>Modellerad kostnadsminskning vid händelse</th><th>Basindikator / år</th><th>Beräknad indikator med urval / år</th><th>Beräknad potential / år</th></tr></thead><tbody>${s.rows.sort((a,b)=>(b.reduction??-Infinity)-(a.reduction??-Infinity)).map(r=>`<tr><td>${exRiskButton(EX_RISKS.get(r.riskId))}${r.reason?`<small class="ms-cell-note">${esc(r.reason)}</small>`:''}</td><td>${investmentPercent(r.frequencyReduction)}</td><td>${investmentPercent(r.severityReduction)}</td><td>${measurementMoney(r.baseline)}${measurementProvenanceLabel(r.riskId,'expectedLoss')}</td><td>${measurementMoney(r.residual)}<small class="ms-cell-note">Modellberäkning efter kontrollpåverkan</small></td><td>${measurementMoney(r.reduction)}<small class="ms-cell-note">Beräknad differens · modellpotential</small></td></tr>`).join('')}</tbody></table></div>${s.selectedIds.length>1?`<h4>Vad varje åtgärd tillför i kombinationen</h4><p class="ex-note">Skillnaden om en åtgärd tas bort och de övriga behålls. Bidragen ska inte summeras.</p><div class="ex-table-wrap"><table class="ex-table"><thead><tr><th>Åtgärd</th><th>Beräknat ytterligare bidrag / år</th></tr></thead><tbody>${s.selectedIds.map(id=>{const without=evaluateInvestment(DATA.measurement,EX_DATA.controls,s.selectedIds.filter(x=>x!==id)),byId=new Map(without.rows.map(r=>[r.riskId,r]));const value=s.rows.filter(r=>r.reduction!=null).reduce((total,r)=>total+(byId.get(r.riskId)?.residual??r.baseline)-r.residual,0);return `<tr><td>${esc(EX_CONTROLS.get(id).title)}</td><td>${measurementMoney(value)}</td></tr>`;}).join('')}</tbody></table></div>`:''}${investmentMethod()}</section>`;
}
function renderControlAnalysis() {
  const selected=[...publicationState.selected];
  const controls=EX_DATA.controls.filter(c=>(publicationState.controlDriver!=='authority'||exAuthority(c)&&(exState.controlScenario==='all'||c.scenario===exState.controlScenario))&&(!publicationState.controlSearch||(c.title+' '+c.id).toLocaleLowerCase('sv').includes(publicationState.controlSearch.toLocaleLowerCase('sv'))));
  const s=evaluateInvestment(DATA.measurement,EX_DATA.controls,selected),ranked=rankInvestments(DATA.measurement,EX_DATA.controls,controls);
  $('#main').innerHTML=`${measurementControlTabs()}<div class="ex-page-head"><div><div class="eyebrow">Motåtgärdsanalys</div><h2>Prioritera föreslagna motåtgärder</h2><p>Undersök hur åtgärderna kan minska riskkostnaderna och vad de tillför tillsammans. Samtliga kontroller är förslag; ingen är införd.</p></div><div class="ex-segment"><button class="btn ${publicationState.controlDriver==='all'?'active':''}" data-pub-driver="all" aria-pressed="${publicationState.controlDriver==='all'}">Alla åtgärder</button><button class="btn ${publicationState.controlDriver==='authority'?'active':''}" data-pub-driver="authority" aria-pressed="${publicationState.controlDriver==='authority'}">Myndighetsdrivna</button></div></div><div class="ms-scope"><span>Utgångsläge: utan införda motåtgärder</span><span>Modellerad potential · granskad indikator · ${esc(DATA.measurement.provenance.currency)}</span></div><div class="ms-filter-row"><label>Sök åtgärd <input id="msControlSearch" type="search" placeholder="Namn eller ID" value="${esc(publicationState.controlSearch)}" aria-label="Sök åtgärder för analys"></label>${publicationState.controlDriver==='authority'?`<label>Åtgärdsscenario <select id="msControlScenario"><option value="all" ${exState.controlScenario==='all'?'selected':''}>Alla scenarier</option>${Object.entries(EX_AUTHORITY_SCENARIOS).map(([id,label])=>`<option value="${id}" ${exState.controlScenario===id?'selected':''}>${esc(label)}</option>`).join('')}</select></label>`:''}<button class="btn" id="msSelectVisible">Välj alla ${controls.length} i filtret</button>${selected.length?'<button class="btn" id="msClearSelected">Rensa val</button>':''}<button class="btn" data-pub-scenario-results>Visa mitt urval (${selected.length})</button></div><section class="ms-panel"><h3>Jämför åtgärder var för sig</h3>${measurementControlProvenance()}<p>Sorterat efter minskning i den granskade kostnadsindikatorn för berörda riskposter när en åtgärd införs ensam. Täckningen anges för varje rad. Höga belopp behöver läsas tillsammans med riskernas osäkerhet, åtgärdens mandat och dess framtida genomförandekostnad.</p><div class="ex-table-wrap ms-investment-table"><table class="ex-table"><thead><tr><th>Välj</th><th>Föreslagen motåtgärd</th><th>Beräknad potential / år</th><th>Modellerad andel av underlaget</th><th>Kostnadsunderlag</th><th>I topp 50</th></tr></thead><tbody>${ranked.map(r=>`<tr class="${publicationState.selected.has(r.control.id)?'ms-selected-row':''}"><td><input type="checkbox" data-pub-scenario-control="${esc(r.control.id)}" aria-label="Välj ${esc(r.control.title)}" ${publicationState.selected.has(r.control.id)?'checked':''}></td><td><button class="ex-text-link" data-ex-control="${esc(r.control.id)}">${esc(r.control.title)}</button><small class="ms-cell-note">${esc(r.control.id)} · Föreslagen${investmentScaleNotes(r.control.riskIds).length?' · Kostnadsnivå behöver granskas':''}${r.adverseCount?` · ${r.adverseCount} ${r.adverseCount===1?'risk':'risker'} med ökad modellkostnad`:''}</small></td><td>${measurementMoney(r.reduction)}</td><td>${investmentPercent(r.reductionFraction)}</td><td>${r.pricedCount} / ${r.affectedCount} risker</td><td>${r.control.riskIds.filter(id=>RANKING.topRiskIds.has(id)).length}</td></tr>`).join('')||'<tr><td colspan="6">Ingen åtgärd matchar filtret.</td></tr>'}</tbody></table></div><p class="ex-note">Negativ minskning innebär en ökning i modellen. Okänd kostnad eller saknat effektunderlag redovisas som odefinierat. Kontrollerna kan inte rangordnas efter nettonytta innan genomförandekostnader finns.</p></section><div id="msScenarioResults" class="ms-investment-results" aria-live="polite">${investmentSelection(s)}</div>`;
  if($('#msControlScenario'))$('#msControlScenario').onchange=e=>{exState.controlScenario=e.target.value;renderControlAnalysis();exSyncRoute();};
  $('#msSelectVisible').onclick=()=>{for(const c of controls)publicationState.selected.add(c.id);renderControlAnalysis();exSyncRoute();};
  if($('#msClearSelected'))$('#msClearSelected').onclick=()=>{publicationState.selected.clear();renderControlAnalysis();exSyncRoute();};
  let timer;$('#msControlSearch').oninput=e=>{const value=e.target.value;clearTimeout(timer);timer=setTimeout(()=>{publicationState.controlSearch=value;renderControlAnalysis();const input=$('#msControlSearch');input.focus();input.setSelectionRange(value.length,value.length);},160);};
}
function reportFigure(id) {
  return renderReportFigure(id,REPORT,DATA.reportMeasurement,RISKS,EX_DATA.controls);
}

function renderReport() {
  const chapter=REPORT.chapters.find(c=>c.id===publicationState.chapter),interviewCount=INTERVIEWS.interviews.length;
  if(!chapter) {
    $('#main').innerHTML=`<div class="rp-cover"><div><div class="rp-section-label">Analysrapport · ${esc(REPORT.date)}</div><h2>${esc(REPORT.title)}</h2><p class="rp-cover-lead">${esc(REPORT.description)}</p><div class="ex-actions"><button class="btn active" data-pub-chapter="sammanfattning">Börja läsa</button><a class="btn" href="report/rapport.pdf" target="_blank">Ladda ner rapporten (PDF)</a><a class="ex-text-link" href="report/" target="_blank">Utskriftsvänlig läsversion</a></div><p class="ex-note">${REPORT.chapters.length} kapitel och bilagor · analys, åtgärdsförslag och källor</p></div><aside><strong class="rp-big-number">${RISKS.length}</strong><p>risker från vägval till byggstart.</p><div class="rp-cover-index"><span class="rp-section-label">I rapporten</span>${[...new Set(REPORT.chapters.map(c=>c.part))].map((part,i)=>`<button class="ex-text-link" data-pub-chapter="${REPORT.chapters.find(c=>c.part===part).id}"><span>${String(i+1).padStart(2,'0')}</span>${esc(part)}</button>`).join('')}</div></aside></div><div class="rp-three"><section><span>01</span><div><h3>Riskbild och processer</h3><p>Ekonomisk betydelse och var i prövningskedjan riskerna uppstår.</p></div></section><section><span>02</span><div><h3>Myndigheternas åtgärder</h3><p>Scenarier, överlapp och genomförandeförutsättningar.</p></div></section><section><span>03</span><div><h3>Intervjuer och samlad analys</h3><p>Företagens erfarenheter av underlagskrav, handläggning och väntetid.</p></div></section></div><section class="rp-manuscript-note"><h3>Rapportens underlag</h3><p>${esc(REPORT.extent)} Metodbilagorna redovisar beräkning, datakvalitet och begränsningar.</p><p class="ex-note">${interviewCount?`Rapporten bygger på ${interviewCount} intervjukällor.`:'Intervjukapitlen är förberedda. Inga citat eller intervjufynd har konstruerats.'}</p></section>`;
  } else {
    const index=REPORT.chapters.indexOf(chapter),next=REPORT.chapters[index+1],previous=REPORT.chapters[index-1];
    $('#main').innerHTML=`<div class="rp-reader"><aside class="rp-toc"><button class="ex-text-link" data-pub-report-cover>Rapportens startsida</button><h3>I rapporten</h3><p>${index+1} av ${REPORT.chapters.length} avsnitt</p><progress value="${index+1}" max="${REPORT.chapters.length}"></progress><button class="btn rp-mobile-toc-toggle" data-pub-toggle-toc aria-expanded="false" aria-controls="rpChapterNav">Innehåll · avsnitt ${index+1} av ${REPORT.chapters.length}</button><nav id="rpChapterNav" aria-label="Rapportens kapitel">${REPORT.chapters.map((c,i)=>`${i===0||REPORT.chapters[i-1].part!==c.part?`<div class="rp-toc-part">${esc(c.part)}</div>`:''}<button class="${c.id===chapter.id?'active':''}" ${c.id===chapter.id?'aria-current="page"':''} data-pub-chapter="${esc(c.id)}"><span>${esc(c.number)}</span>${esc(c.title)}</button>`).join('')}</nav><a class="btn" href="report/rapport.pdf" target="_blank">Rapport (PDF)</a></aside><article class="rp-article">${renderReportChapter(chapter,REPORT,INTERVIEWS,{figure:reportFigure})}<footer class="rp-chapter-footer"><span>${esc(REPORT.date)}</span><nav aria-label="Bläddra i rapporten">${previous?`<button class="ex-text-link" data-pub-chapter="${esc(previous.id)}">← Föregående: ${esc(previous.title)}</button>`:''}${next?`<button class="ex-text-link" data-pub-chapter="${esc(next.id)}">Nästa: ${esc(next.title)}</button>`:'<button class="ex-text-link" data-pub-report-cover>Till rapportens startsida</button>'}</nav></footer></article></div>`;
  }
}
function publicationReadRoute() {
  const p=new URLSearchParams(location.search);
  Object.assign(publicationState,{controlTab:'register',selected:new Set(),controlDriver:'authority',analysisChart:'',analysisTop:false,chapter:null,expandedRisk:null});
  const units=new Set(RISKS.map(r=>riskMetric(r.risk_id,'likelihood')?.unit).filter(Boolean));
  $('#sort').querySelector('[value=rank]').textContent=DATA.presentation.costPriority?'Sortera: Kostnadsrangordning':'Sortera: BTL-rangordning';
  $('#sort').querySelector('[value=loss]').textContent=`Sortera: Högst ${REVIEWED_COST?'granskad kostnadsindikator':CENTRAL_COST?'medianbaserad kostnadsindikator':LOSS_STATISTIC==='median'?'medianförlust':'förväntad årskostnad'}`;
  if(units.size>1){const option=$('#sort').querySelector('[value=likelihood]');option.disabled=true;option.textContent='Händelsemått: olika enheter kan inte jämföras';}
  if(p.get('view')==='controls'&&(p.get('controltab')==='analysis'||!p.has('risk')&&p.get('tab')==='analysis'))publicationState.controlTab='analysis';
  for(const id of (p.get('selected')||'').split(','))if(EX_CONTROLS.has(id))publicationState.selected.add(id);
  if(['all','authority'].includes(p.get('analysisdriver')))publicationState.controlDriver=p.get('analysisdriver');
  if(CHARTS.includes(p.get('analysischart')))publicationState.analysisChart=p.get('analysischart');
  publicationState.analysisTop=p.get('analysistop')==='1';
  if(p.get('analysisscenario')==='all'||EX_AUTHORITY_SCENARIOS[p.get('analysisscenario')])exState.controlScenario=p.get('analysisscenario');
  if(REPORT.chapters.some(c=>c.id===p.get('chapter')))publicationState.chapter=p.get('chapter');
}
function publicationInit() {
  publicationReadRoute();
  document.addEventListener('click',e=> {
    const el=e.target.closest('button');if(!el)return;
    if(el.dataset.pubAnalyseControl){publicationState.selected=new Set([el.dataset.pubAnalyseControl]);publicationState.controlTab='analysis';publicationState.controlDriver=exAuthority(EX_CONTROLS.get(el.dataset.pubAnalyseControl))?'authority':'all';exCloseDialog();setView('controls');exSyncRoute();}
    else if(el.dataset.pubControlTab){publicationState.controlTab=el.dataset.pubControlTab;setView('controls');exSyncRoute();}
    else if(el.hasAttribute('data-pub-controls-analysis')){publicationState.controlTab='analysis';exCloseDialog();setView('controls');exSyncRoute();}
    else if(el.dataset.pubDriver){publicationState.controlDriver=el.dataset.pubDriver;renderControlAnalysis();exSyncRoute();}
    else if(el.hasAttribute('data-pub-toggle-toc')){const aside=el.closest('.rp-toc');const open=aside.classList.toggle('open');el.setAttribute('aria-expanded',String(open));if(open)aside.querySelector('[aria-current]')?.scrollIntoView({block:'nearest'});}
    else if(el.hasAttribute('data-pub-scenario-results')){$('#msScenarioResults')?.scrollIntoView({behavior:'smooth',block:'start'});}
    else if(el.dataset.pubChapter){publicationState.chapter=el.dataset.pubChapter;setView('report');window.scrollTo({top:0,left:0,behavior:'instant'});exSyncRoute();}
    else if(el.hasAttribute('data-pub-report-cover')){publicationState.chapter=null;setView('report');window.scrollTo({top:0,left:0,behavior:'instant'});exSyncRoute();}
    else if(el.dataset.pubExpandRisk){publicationState.expandedRisk=publicationState.expandedRisk===el.dataset.pubExpandRisk?null:el.dataset.pubExpandRisk;renderCompactRisks();}
  });
  document.addEventListener('keydown',e=>{const el=e.target.closest('[data-pub-control-tab]');if(!el||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();publicationState.controlTab=e.key==='Home'?'register':e.key==='End'?'analysis':publicationState.controlTab==='analysis'?'register':'analysis';renderControls();exSyncRoute();document.querySelector(`[data-pub-control-tab="${publicationState.controlTab}"]`)?.focus();});
  document.addEventListener('change',e=>{const el=e.target;if(el.dataset.pubScenarioControl){el.checked?publicationState.selected.add(el.dataset.pubScenarioControl):publicationState.selected.delete(el.dataset.pubScenarioControl);renderControlAnalysis();exSyncRoute();$('#main').querySelector(`[data-pub-scenario-control="${CSS.escape(el.dataset.pubScenarioControl)}"]`)?.focus();}});
}
function publicationRoute(u) {
  for(const key of ['selected','chapter','analysischart','analysistop','analysisdriver','controltab','analysisscenario'])u.searchParams.delete(key);
  if(state.view==='controls'&&publicationState.controlTab==='analysis') {
    u.searchParams.set(exState.dialog?.type==='risk'?'controltab':'tab','analysis');
    if(publicationState.selected.size)u.searchParams.set('selected',[...publicationState.selected].sort().join(','));
    if(publicationState.controlDriver!=='authority')u.searchParams.set('analysisdriver',publicationState.controlDriver);
    else if(exState.controlScenario!==EX_AUTHORITY_MAIN)u.searchParams.set('analysisscenario',exState.controlScenario);
  }
  if(state.view==='analysis') {
    if(publicationState.analysisChart)u.searchParams.set('analysischart',publicationState.analysisChart);
    if(publicationState.analysisTop)u.searchParams.set('analysistop','1');
  }
  if(state.view==='report'&&publicationState.chapter)u.searchParams.set('chapter',publicationState.chapter);
}
